// === Tab: mySketch ===
let seed;
let colors = [];

function setup() {
  // pixelDensity(5);
  createCanvas(windowWidth, windowHeight);
  seed = int(random(1000));
  colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  randomSeed(seed);
  background(0, 0, 95, 100);
  translate(width / 2, height / 2);
  for (let i = 0; i < 20; i++) {
    colors[0] = color(10, 70, 75, random(100, 50));
    colors[1] = color(30, 50, 85, random(20, 50));
    colors[2] = color(80, 60, 75, random(100, 50));
    colors[3] = color(130, 80, 85, random(20, 50));
    colors[4] = color(200, 40, 65, random(100, 50));
    circleForm(0, 0, width * 0.25 * (i+1));
  }
}

function circleForm(x, y, d) {

  let branch = int(random(15, 200));
  let ang = TAU / branch;
  let angles = [];
  for (let i = 0; i < branch; i++) {
    angles.push(ang * (i + iteration(0.1, 0.25)));
  }
  for (let i = 0; i < branch; i++) {
    let ang1 = angles[i];
    let ang2 = angles[(i + int(random(6))) % angles.length];
    let dd = d * iteration(0.1, 1);
    noFill();
    stroke(lerpColor(random(colors), random(colors), random()));
    strokeCap(SQUARE);
    strokeWeight(random(300));
    arc(x, y, dd, dd, ang1, ang2);
  }

}

function iteration(s, e) {
  let t = random(1000);
  let v = random(0.005, 0.03);
  return map(sin(t + frameCount * v), -1, 1, s, e);
}

